function showScorelessStep(step,{persist=true}={}){scorelessStep=step;for(const [name,id]of [['count','scorelessCountStep'],['mode','scorelessModeStep'],['winType','scorelessWinTypeStep'],['coopType','scorelessCoopTypeStep'],['team','scorelessTeamStep']])$(id).hidden=step!==name;const titles={count:'플레이 인원 선택',mode:'기록 방식 변경',winType:'승패 기록',coopType:'협력 기록 방식',team:'팀 구성'};$('scorelessSetupTitle').textContent=titles[step]||'기록 방식 변경';$('scorelessModeBack').hidden=pendingScoreless?.source==='board';$('scorelessSetupGame').hidden=true;$('scorelessSetupError').textContent='';const active=api.getResultEntry?.(),current=active?.mode||'score',currentCoop=active?.mode==='coop'?(Array.isArray(active.missionAttempts)?'mission':active.coopKind||'score'):'',options=[['score',$('scoreModeOption')],['win',$('scorelessWinMode')],['rank',$('scorelessRankMode')],['coop',$('scorelessCoopMode')]],coopOptions=[['score',$('scorelessCoopScoreMode')],['mission',$('scorelessMissionMode')],['difficulty',$('scorelessCoopDifficultyMode')],['campaign',$('scorelessCoopCampaignMode')]];for(const [mode,button]of options)button.hidden=step!=='mode'||!['win','coop'].includes(mode)&&mode===current;for(const [kind,button]of coopOptions)button.hidden=step!=='coopType'||kind===currentCoop;if(step==='coopType')renderCoopRecent();$('scorelessSoloWinMode').hidden=step!=='winType'||current==='win';$('scorelessTeamWinMode').hidden=step!=='winType'||current==='team';if(persist&&['count','mode','board'].includes(step))persistScorelessDraft(step);if(step==='mode')options.find(([,button])=>!button.hidden)?.[1].focus({preventScroll:true});if(step==='winType')[$('scorelessSoloWinMode'),$('scorelessTeamWinMode')].find(button=>!button.hidden)?.focus({preventScroll:true});if(step==='coopType')coopOptions.find(([,button])=>!button.hidden)?.[1].focus({preventScroll:true});}
function renderScorelessPlayerChoices(){const box=$('scorelessPlayerChips'),choices=savedPlayerChoices(records);box.replaceChildren();$('scorelessSavedPlayers').hidden=!choices.length;for(const choice of choices){const button=node('button',choice.name,'saved-player-chip'),key=choice.name.normalize('NFKC').toLocaleLowerCase();button.type='button';button.setAttribute('aria-pressed',String(scorelessSelectedPlayers.has(key)));button.onclick=()=>{if(scorelessSelectedPlayers.has(key))scorelessSelectedPlayers.delete(key);else scorelessSelectedPlayers.add(key);setScorelessCount(Math.max(Number($('scorelessCount').value)||1,scorelessSelectedPlayers.size));renderScorelessPlayerChoices();persistScorelessDraft('count');};box.append(button);}}
